package com.hexxon.api.analytics;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name = "marketing_events") public class MarketingEvent { @Id private UUID id; @Enumerated(EnumType.STRING) @Column(name = "event_type", nullable = false) private MarketingEventType eventType; @Column(name = "page_path", nullable = false) private String pagePath; @Column(name = "product_slug") private String productSlug; @Column(name = "anonymous_id") private String anonymousId; private String source; @Column(name = "created_at", nullable = false) private Instant createdAt; protected MarketingEvent() {} public MarketingEvent(MarketingEventType eventType, String pagePath, String productSlug, String anonymousId, String source) { this.id = UUID.randomUUID(); this.eventType = eventType; this.pagePath = pagePath; this.productSlug = productSlug; this.anonymousId = anonymousId; this.source = source; this.createdAt = Instant.now(); } }
